from pathlib import Path
import json
R=Path('/home/isp/wsps/cyf'); E=R/'docs/implementation/evidence/spec-full-refresh-20261107'; changed=[]
def edit(name, pairs):
 p=R/name; old=p.read_text(); s=old
 for a,b in pairs:
  if a not in s: raise RuntimeError((name,a))
  s=s.replace(a,b)
 if s!=old:
  backup=E/'originals'/(name+'.txt'); backup.parent.mkdir(parents=True,exist_ok=True)
  if not backup.exists(): backup.write_text(old)
  p.write_text(s); changed.append(name)
